package com.ruoyi.web.controller.portal;
import java.util.Map; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.web.bind.annotation.*; import com.ruoyi.common.annotation.Anonymous; import com.ruoyi.common.core.controller.BaseController; import com.ruoyi.common.core.domain.AjaxResult; import com.ruoyi.framework.web.service.MpTokenService; import com.ruoyi.system.service.IYcMeetingFeedbackService; import jakarta.servlet.http.HttpServletRequest;
@Anonymous @RestController @RequestMapping("/portal/meeting/feedback") public class PortalFeedbackController extends BaseController { @Autowired private IYcMeetingFeedbackService service; @Autowired private MpTokenService tokens; @PostMapping public AjaxResult submit(@RequestBody Map<String,Object> body,HttpServletRequest req){Integer rating=body.get("rating")==null?null:Integer.valueOf(String.valueOf(body.get("rating")));return toAjax(service.submit(Long.valueOf(String.valueOf(body.get("activityId"))),rating,String.valueOf(body.getOrDefault("content","")),tokens.getLoginUser(req)));} }
